<template>
 <view class="shell">
  <view class="rail">
   <view class="brand" @click="c.go('home')"><text class="brand-mark">✳</text><view><text class="brand-title">寰校通</text><text class="eyebrow">UNIVERSE / CAMPUS</text></view></view>
   <text class="nav-caption">{{c.t('我的校园')}}</text>
   <button role="button" tabindex="0" v-for="tab in c.mainTabs" :key="tab.key" class="rail-link" :class="{active:c.section===tab.key}" @click="c.go(tab.key)"><UiIcon :name="tab.icon"/><text>{{c.t(tab.label)}}</text><text v-if="tab.key==='messages'&&c.overview.unread" class="badge">{{c.overview.unread}}</text></button>
   <text class="nav-caption">{{c.t('校园服务')}}</text>
   <button role="button" tabindex="0" v-for="s in c.services" :key="s.key" class="rail-link" :class="{active:c.section===s.key}" @click="c.go(s.key)"><UiIcon :name="s.icon"/><text>{{c.t(s.label)}}</text></button>
   <view class="rail-bottom"><view class="rail-note"><text class="eyebrow">A LITTLE CLOSER.</text><text>{{c.t('让校园生活，近一点。')}}</text></view><button role="button" tabindex="0" class="quiet" @click="c.drawer=true"><UiIcon name="globe" :size="18"/> {{langLabel}}</button></view>
  </view>
  <view class="workspace">
   <view class="topbar"><view class="top-left"><button role="button" tabindex="0" class="icon-button mobile-menu" @click="c.drawer=true" :aria-label="c.t('打开菜单')"><UiIcon name="menu"/></button><view><text class="top-brand">寰校通 <text class="thin">UniVerse</text></text><text class="top-caption">{{c.t('多语校园智慧生活服务平台')}}</text></view></view><view class="row"><text class="connected desktop-only"><text class="dot"/>{{c.online?c.t('校园已连接'):c.t('连接中')}}</text><button role="button" tabindex="0" class="icon-button" @click="c.modal='checkin'" :aria-label="c.t('扫码签到')"><UiIcon name="scan"/></button><button role="button" tabindex="0" class="avatar small" @click="c.user?c.go('me'):c.modal='login'">{{c.user?c.user.name.slice(0,1):'U'}}</button></view></view>
   <view class="content">
    <view v-if="c.section!=='home'" class="page-heading"><button role="button" tabindex="0" class="icon-button back" @click="c.go('home')" :aria-label="c.t('返回首页')"><UiIcon name="back"/></button><view><text class="eyebrow">UNIVERSE / {{c.section.toUpperCase()}}</text><text class="page-title">{{c.title}}</text></view></view>
    <view v-if="c.error" class="error-banner"><text>{{c.error}}</text><button role="button" tabindex="0" class="text-button" @click="c.go(c.section)">{{c.t('重试')}}</button></view>
    <view v-if="c.loading" class="loading-line"><view/></view>

    <template v-if="c.section==='home'">
     <view class="hero"><view class="hero-copy"><text class="eyebrow"><text class="dot"/> YOUR CAMPUS, TOGETHER.</text><text class="hero-title">{{c.t('新的日常，')}}<text class="hero-accent">{{c.t('一起开启。')}}</text></text><text class="hero-description">{{c.t('遇见同学，安排生活。')}}<text class="block">{{c.t('从一件小事开始，慢慢熟悉这里。')}}</text></text><button role="button" tabindex="0" class="primary hero-button" @click="c.go('assistant')">{{c.t('让伙伴帮我办事')}} <text>↗</text></button></view><view class="hero-art" aria-hidden="true"><view class="orbit orbit-one"/><view class="orbit orbit-two"/><view class="sun"><text>⌣</text></view><view class="paper paper-one"><text>HELLO,</text><text>NEW DAY.</text></view><view class="paper paper-two"><text>你好</text><text>Hello · Привет</text></view><text class="art-star">✳</text></view><text class="hero-index">01 / CAMPUS LIFE</text></view>
     <view class="section-heading"><text class="section-title">{{c.t('今天，从这里出发')}}</text><button role="button" tabindex="0" class="text-button" @click="c.drawer=true">{{c.t('全部服务')}} ↗</button></view>
     <view class="service-grid"><button role="button" tabindex="0" v-for="(s,i) in c.services" :key="s.key" class="service-card" :class="s.tone" @click="c.go(s.key)"><view class="service-top"><text class="eyebrow">0{{i+1}} / CAMPUS</text><text class="circle-arrow">↗</text></view><UiIcon :name="s.icon" :size="36"/><text class="service-name">{{c.t(s.label)}}</text><text class="service-desc">{{c.t(s.desc)}}</text></button></view>
     <view class="home-grid">
      <view class="panel agenda"><view class="section-heading"><view><text class="eyebrow">YOUR NEXT CHAPTER</text><text class="section-title">{{c.t('我的日程')}}</text></view><button role="button" tabindex="0" class="text-button" @click="c.go('bookings')">{{c.t('全部')}} ↗</button></view><view v-if="!c.user" class="empty"><UiIcon name="calendar" :size="32"/><text>{{c.t('登录后，日程会在这里等你。')}}</text><button role="button" tabindex="0" class="soft" @click="c.modal='login'">{{c.t('登录校园账号')}}</button></view><template v-else><view v-if="c.plan" class="plan-preview" @click="c.go('assistant')"><text class="mini-label">{{c.t('办事计划')}} · {{c.plan.progress}} / {{c.plan.total}}</text><text class="strong">{{c.plan.source}}</text><view class="progress-track"><view :style="{width:(c.plan.progress/c.plan.total*100)+'%'}"/></view><text class="muted">{{c.plan.instruction}}</text></view><view v-for="b in c.overview.bookings.slice(0,3)" :key="b.id" class="agenda-row" @click="showReceipt(b)"><view class="date-tile"><text>{{b.day.slice(5,7)}} /</text><text class="date-number">{{b.day.slice(-2)}}</text></view><view class="grow"><text class="strong">{{b.name}}</text><text class="muted">{{b.time}} · {{b.status_label}}</text></view><text>↗</text></view><view v-if="!c.overview.bookings.length&&!c.plan" class="empty"><text>{{c.t('日程还很轻，给自己留一点新可能。')}}</text><button role="button" tabindex="0" class="soft" @click="c.go('booking')">{{c.t('预约一个位置')}} ↗</button></view></template></view>
      <view class="side-stack"><view class="panel weather-card"><view class="section-heading"><text class="eyebrow">OUTSIDE / {{c.t('当地天气')}}</text><button role="button" tabindex="0" class="icon-button" @click="c.locate()" :disabled="c.weatherBusy" :aria-label="c.t('定位')"><UiIcon name="location" :size="19"/></button></view><template v-if="c.weather"><text class="weather-place">{{weatherPlace}}</text><view class="weather-reading"><text>{{weatherTemperature}}°</text><text class="weather-sun">☼</text></view><text class="muted">{{weatherDescription}}</text></template><template v-else><text class="weather-heading">{{c.t('出门前，看一眼天气。')}}</text><text class="muted">{{c.t('设备定位优先，也可以自己选城市。')}}</text></template><text v-if="c.weatherStatus" class="mini-label">{{c.weatherStatus}}</text><view class="row split weather-actions"><button role="button" tabindex="0" class="text-button" @click="c.locate()">{{c.weatherBusy?c.t('定位中…'):c.t('获取位置')}} ↗</button><button role="button" tabindex="0" class="text-button" @click="c.modal='weather'">{{c.t('选择城市')}}</button></view></view><button role="button" tabindex="0" class="map-entry" @click="c.openWeb('/campus-map/')"><UiIcon name="map" :size="30"/><view class="grow"><text class="strong">{{c.t('3D 校园地图')}}</text><text class="muted">{{c.t('从入口，一直走到你的座位。')}}</text></view><text>↗</text></button></view>
     </view>
     <view v-if="c.bootstrap.announcements.length" class="panel announcement"><UiIcon name="bell"/><view class="grow"><text class="strong">{{c.bootstrap.announcements[0].title}}</text><text class="muted">{{c.bootstrap.announcements[0].content}}</text></view></view>
     <text class="page-foot">UNIVERSE · {{c.t('分享与帮助，让校园生活轻松一点。')}}</text>
    </template>

    <template v-if="c.section==='booking'">
     <view class="panel booking-filters"><text class="eyebrow">01 {{c.t('选场地')}} / 02 {{c.t('选楼层')}} / 03 {{c.t('确认预约')}}</text><scroll-view scroll-x class="horizontal-scroll"><view class="chips"><button role="button" tabindex="0" v-for="k in c.bootstrap.kinds" :key="k.value" class="chip" :class="{selected:c.filters.kind===k.value}" @click="c.chooseFilter('kind',k.value)">{{c.t(k.label)}}</button></view></scroll-view><view class="quick-dates"><button role="button" tabindex="0" class="text-button" @click="c.chooseFilter('day',c.bootstrap.today)">{{c.t('今天')}}</button><button role="button" tabindex="0" class="text-button" @click="c.chooseFilter('day',tomorrow)">{{c.t('明天')}}</button></view><view class="filter-row"><picker mode="date" :value="c.filters.day" :start="c.bootstrap.today" @change="c.chooseFilter('day',$event.detail.value)"><view class="picker-field"><UiIcon name="calendar" :size="18"/>{{c.filters.day}}<text>⌄</text></view></picker><picker :range="c.bootstrap.slots" range-key="label" @change="c.chooseFilter('slot',c.bootstrap.slots[$event.detail.value].value)"><view class="picker-field">{{slotLabel(c.filters.slot)}}<text>⌄</text></view></picker></view><view v-if="c.filters.kind==='study'" class="building-grid"><button role="button" tabindex="0" v-for="b in c.bootstrap.buildings" :key="b.value" class="building" :class="{selected:c.filters.building===b.value}" @click="c.chooseFilter('building',b.value)"><text class="building-glyph">▤</text><text>{{c.t(b.label)}}</text></button></view></view>
     <view class="panel seat-panel"><view class="section-heading"><view><text class="section-title">{{c.t('选择你的位置')}}</text><text class="muted">{{c.available}} {{c.t('个位置可预约')}}</text></view><button role="button" tabindex="0" class="text-button" @click="c.openWeb('/campus-map/?day='+c.filters.day+'&slot='+c.filters.slot)">3D ↗</button></view><view class="chips"><button role="button" tabindex="0" v-for="floor in c.floors" :key="floor" class="chip" :class="{selected:c.filters.floor===floor}" @click="c.filters.floor=floor">{{floor}} F</button></view><view class="room-front">{{c.t('前方 / 公共通道')}}</view><view class="seat-grid"><button role="button" tabindex="0" v-for="v in c.floorVenues" :key="v.id" class="seat" :class="v.state" @click="c.chooseSeat(v)"><text class="seat-symbol">{{c.filters.kind==='study'?'▱':'▥'}}</text><text>{{seatLabel(v)}}</text></button></view><view v-if="!c.floorVenues.length" class="empty">{{c.t('这里暂时没有开放位置，请换个楼栋。')}}</view><view class="seat-legend"><view><text class="legend-dot free"/>{{c.t('可预约')}}</view><view><text class="legend-dot taken"/>{{c.t('已占用')}}</view><view><text class="legend-dot hold"/>{{c.t('候补保留 / 不可用')}}</view></view><text class="fine-print">{{c.t('颜色表示所选日期和时段的预约状态，预约前请核对地点。')}}</text></view>
    </template>

    <template v-if="c.section==='assistant'">
     <view class="assistant-grid"><view class="panel chat-panel"><view class="companion-heading"><view class="companion-orb">✳</view><view><text class="strong">{{c.t('你的校园伙伴')}}</text><text class="muted">{{c.t('一句话，把想做的事变成计划。')}}</text></view></view><view class="conversation"><view class="bubble assistant">{{c.t('你好！可以问我学习与日常问题，也可以一起安排校园生活。')}}</view><view v-for="(m,i) in c.conversation" :key="i" class="bubble" :class="m.role"><text selectable>{{m.content}}</text></view><view v-if="!c.conversation.length" class="suggestions"><button role="button" tabindex="0" class="suggestion" @click="c.sendMessage('我刚来学校，想认识同学，周末打羽毛球')">{{c.t('认识同学，周末打羽毛球')}} ↗</button><button role="button" tabindex="0" class="suggestion" @click="c.assistantSelect('kind','study')">{{c.t('帮我预约自习室')}} ↗</button></view><view v-if="c.busy" class="thinking">{{c.t('伙伴正在整理…')}}</view><view v-if="c.assistant.message&&!c.conversation.length" class="muted">{{c.assistant.message}}</view></view>
      <view class="assistant-options"><view v-if="c.assistant.phase==='ask_kind'" class="chips"><button role="button" tabindex="0" v-for="k in c.bootstrap.kinds" :key="k.value" class="chip" @click="c.assistantSelect('kind',k.value)">{{c.t(k.label)}}</button></view><view v-if="c.assistant.phase==='ask_building'" class="chips"><button role="button" tabindex="0" v-for="b in c.assistant.buildings" :key="b.value" class="chip" @click="c.assistantSelect('building',b.value)">{{b.label}}</button></view><view v-if="c.assistant.phase==='ask_day'" class="row"><picker mode="date" :value="c.assistantDay" :start="c.bootstrap.today" @change="c.assistantDay=$event.detail.value"><view class="picker-field">{{c.assistantDay}} ⌄</view></picker><button role="button" tabindex="0" class="soft" @click="c.assistantSelect('day',c.assistantDay)">{{c.t('确认日期')}}</button></view><view v-if="c.assistant.phase==='ask_slot'" class="chips"><button role="button" tabindex="0" v-for="s in c.assistant.slots" :key="s.value" class="chip" :disabled="!s.count" @click="c.assistantSelect('slot',s.value)">{{s.label}} · {{s.count}}</button></view><view v-if="c.assistant.phase==='choose_venue'" class="choice-list"><button role="button" tabindex="0" v-for="v in c.assistant.venues" :key="v.id" class="choice" @click="c.confirmAssistant(v)"><text>{{v.name}}</text><text>{{v.day}} · {{v.slot}} ↗</text></button><text v-if="!c.assistant.venues.length" class="muted">{{c.assistant.message}}</text></view><view v-if="c.assistant.actions" class="chips"><button role="button" tabindex="0" v-for="a in c.assistant.actions" :key="a.url" class="chip" @click="c.openWeb(a.url)">{{a.label}} ↗</button></view></view>
      <view class="composer-area"><view class="composer"><textarea v-model="c.message" :maxlength="2000" :placeholder="c.t('说说你的想法，或想办的事…')" auto-height :show-confirm-bar="false"/><button role="button" tabindex="0" class="send" :disabled="c.busy||!c.message.trim()" @click="c.sendMessage()">↑</button></view><label class="check-label"><checkbox :checked="c.externalAllowed" color="#285b4a" @click="c.externalAllowed=!c.externalAllowed"/><text>{{c.t('允许复杂问题调用外部 AI')}}</text></label><text class="fine-print">{{c.t('外部调用会发送当前问题及近期对话；校园操作由你确认。')}}</text></view>
     </view><view class="panel plan-panel"><text class="eyebrow">ONE SENTENCE / ONE PLAN</text><text class="section-title">{{c.t('我的办事计划')}}</text><template v-if="c.plan"><text class="plan-source">{{c.plan.source}}</text><view class="progress-track"><view :style="{width:c.plan.progress/c.plan.total*100+'%'}"/></view><view v-for="(s,i) in c.plan.steps" :key="s.key" class="plan-step" :class="{done:s.done,current:c.plan.current===s.key}"><text class="step-number">{{s.done?'✓':i+1}}</text><view><text class="strong">{{s.label}}</text><text v-if="s.evidence" class="mini-label">{{s.evidence.label}}</text></view></view><text class="muted plan-instruction">{{c.plan.instruction}}</text><button role="button" tabindex="0" v-if="!c.plan.accepted" class="primary full" :disabled="c.busy" @click="c.planAction('accept')">{{c.t('确认这个计划')}} ↗</button><template v-else-if="c.plan.state==='active'"><view v-if="c.plan.blocked"><button role="button" tabindex="0" class="primary full" @click="c.planAction('rebook')">{{c.t('重新预约')}}</button></view><template v-else-if="c.plan.current==='time'"><picker mode="date" :value="c.planDay" :start="c.bootstrap.today" @change="c.planDay=$event.detail.value"><view class="picker-field">{{c.planDay}} ⌄</view></picker><picker :range="c.bootstrap.slots" range-key="label" @change="c.planSlot=c.bootstrap.slots[$event.detail.value].value"><view class="picker-field">{{slotLabel(c.planSlot)}} ⌄</view></picker><button role="button" tabindex="0" class="primary full" @click="c.planAction('time')">{{c.t('确认时间')}}</button></template><template v-else><button role="button" tabindex="0" v-if="c.plan.current==='health'||c.plan.current==='help'" class="soft full" @click="c.planAction('complete')">{{c.t('已办理，继续计划')}}</button><button role="button" tabindex="0" class="primary full" @click="c.continuePlan()">{{c.t('继续这一步')}} ↗</button><view v-if="c.plan.current==='share'||c.plan.current==='navigate'" class="row"><button role="button" tabindex="0" class="text-button" @click="c.planAction('skip')">{{c.t('暂时跳过')}}</button><button role="button" tabindex="0" v-if="c.plan.current==='navigate'" class="text-button" @click="c.planAction('navigated')">{{c.t('我已查看路线')}}</button></view></template></template><button role="button" tabindex="0" v-if="c.plan.state==='cancelled'" class="soft full" @click="c.planAction('resume')">{{c.t('恢复计划')}}</button><button role="button" tabindex="0" v-if="c.plan.state==='active'" class="text-button plan-end" @click="endPlan">{{c.t('结束计划')}}</button></template><view v-else class="empty"><UiIcon name="spark" :size="36"/><text>{{c.t('告诉伙伴你的想法，计划会在这里逐步展开。')}}</text></view></view></view>
    </template>
    <template v-if="c.section==='messages'">
     <view class="section-heading"><view><text class="section-title">{{c.t('把日常，分享给朋友')}}</text><text class="muted">{{c.t('不同语言，也能轻松聊天。')}}</text></view><button role="button" tabindex="0" class="primary compact" @click="c.modal='friends'">＋ {{c.t('添加好友')}}</button></view>
     <view class="social-grid"><view class="panel"><view class="section-heading"><text class="strong">{{c.t('我的好友')}} <text class="count">{{c.friends.length}}</text></text><button role="button" tabindex="0" class="text-button" @click="c.go('messages')">↻ {{c.t('刷新')}}</button></view><button role="button" tabindex="0" v-for="f in c.friends" :key="f.id" class="friend-row" @click="c.chat(f)"><view class="avatar">{{f.name.slice(0,1)}}</view><view class="grow"><text class="strong">{{f.name}}</text><text class="muted">{{c.t('点击打开对话')}}</text></view><text v-if="f.unread" class="badge">{{f.unread}}</text><text v-else>↗</text></button><view v-if="!c.friends.length" class="empty"><UiIcon name="chat" :size="36"/><text>{{c.t('认识一个新朋友，从打招呼开始。')}}</text><button role="button" tabindex="0" class="soft" @click="c.modal='friends'">{{c.t('找同学')}}</button></view></view>
     <view class="panel notices"><text class="section-title">{{c.t('服务通知')}}</text><view v-for="(n,i) in c.notices" :key="i" class="notice-row"><text class="strong">{{n.title}}</text><text class="muted">{{n.body||n.message}}</text><view class="row"><button role="button" tabindex="0" v-if="n.url" class="text-button" @click="c.openWeb(n.url)">{{c.t('查看详情')}} ↗</button><button role="button" tabindex="0" class="text-button" @click="c.readNotice(n)">{{c.t('标为已读')}}</button></view></view><view v-if="!c.notices.length" class="empty"><text>{{c.t('目前没有未读通知。')}}</text></view></view></view>
     <view class="panel moments"><view class="section-heading"><view><text class="eyebrow">LIFE, IN LITTLE MOMENTS</text><text class="section-title">{{c.t('好友日常')}}</text></view><button role="button" tabindex="0" class="soft" @click="c.modal='moment'">＋ {{c.t('分享日常')}}</button></view><view v-for="m in c.moments" :key="m.id" class="moment-row"><view class="avatar small">{{m.author.slice(0,1)}}</view><view class="grow"><text class="strong">{{m.author}}</text><text class="moment-content">{{m.content}}</text><text class="mini-label">{{formatTime(m.time)}}</text></view></view><view v-if="!c.moments.length" class="empty">{{c.t('记录校园里值得记住的小事。')}}</view></view>
    </template>
    <template v-if="c.section==='me'">
     <view class="profile-hero"><view class="avatar large">{{c.user?c.user.name.slice(0,1):'U'}}</view><view><text class="eyebrow">MY CAMPUS / MY SPACE</text><text class="page-title">{{c.user?c.user.name:c.t('你好，校园伙伴')}}</text><text class="muted">{{c.user?c.user.username:c.t('登录后，连接你的校园生活。')}}</text></view><button role="button" tabindex="0" v-if="!c.user" class="primary" @click="c.modal='login'">{{c.t('登录')}}</button></view>
     <view class="stats-row"><view><text class="stat-number">{{c.overview.bookings.length}}</text><text>{{c.t('我的预约')}}</text></view><view><text class="stat-number">{{c.overview.unread}}</text><text>{{c.t('未读通知')}}</text></view><view><text class="stat-number">{{c.plan?c.plan.progress:0}}</text><text>{{c.t('计划已完成步骤')}}</text></view></view>
     <view class="panel menu-list"><button role="button" tabindex="0" @click="c.go('bookings')"><UiIcon name="calendar"/><text>{{c.t('我的预约与办事卡')}}</text><text>↗</text></button><button role="button" tabindex="0" @click="c.go('assistant')"><UiIcon name="spark"/><text>{{c.t('我的办事计划')}}</text><text>↗</text></button><button role="button" tabindex="0" @click="c.openWeb('/my-services/')"><UiIcon name="bell"/><text>{{c.t('全部服务记录')}}</text><text>↗</text></button><button role="button" tabindex="0" @click="c.modal='checkin'"><UiIcon name="scan"/><text>{{c.t('扫码签到')}}</text><text>↗</text></button><button role="button" tabindex="0" v-if="c.user" @click="c.modal='password'"><UiIcon name="user"/><text>{{c.t('修改密码')}}</text><text>↗</text></button></view>
     <view class="panel"><text class="section-title">{{c.t('界面语言')}}</text><view class="chips language-chips"><button role="button" tabindex="0" v-for="lang in langs" :key="lang.value" class="chip" :class="{selected:c.language===lang.value}" @click="c.setLanguage(lang.value)">{{lang.label}}</button></view><text class="fine-print">{{c.t('同学发布的内容保留原文，聊天译文可展开对照。')}}</text></view><button role="button" tabindex="0" v-if="c.user" class="quiet full" @click="signOut">{{c.t('退出登录')}}</button>
    </template>
    <template v-if="c.section==='forum'">
