   <template v-if="c.modal==='post-detail'&&c.postDetail"><text class="tag">{{c.t(c.postDetail.category)}}</text><text class="post-title">{{c.postDetail.title}}</text><text class="mini-label">{{c.postDetail.author}} · {{formatTime(c.postDetail.created_at)}}</text><text class="body-copy" selectable>{{c.postDetail.content}}</text><button role="button" tabindex="0" class="soft full" @click="c.openWeb('/forum/posts/'+c.postDetail.id+'/')">{{c.t('查看评论与完整帖子')}} ↗</button></template>
   <template v-if="c.modal==='friends'"><text class="muted">{{c.t('搜索账号或昵称，双方互相关注后成为好友。')}}</text><view class="search-row"><input class="field grow" v-model="c.friendQuery" :maxlength="100" :placeholder="c.t('输入至少两个字符')" @confirm="c.searchFriends()"/><button role="button" tabindex="0" class="primary compact" :disabled="c.busy" @click="c.searchFriends()">{{c.t('搜索')}}</button></view><view v-for="p in c.people" :key="p.id" class="friend-row"><view class="avatar">{{p.name.slice(0,1)}}</view><text class="strong grow">{{p.name}}</text><button role="button" tabindex="0" v-if="p.friend" class="soft" @click="c.chat(p)">{{c.t('聊天')}}</button><button role="button" tabindex="0" v-else class="soft" :disabled="p.following||c.busy" @click="c.addFriend(p)">{{p.following?c.t('已关注'):c.t('关注')}}</button></view><view v-if="!c.people.length" class="empty">{{c.t('输入关键词，找到校园里的新朋友。')}}</view></template>
   <template v-if="c.modal==='chat'"><view class="chat-translator">{{c.t('按好友语言偏好翻译，原文始终保留。')}}</view><view v-if="!c.messages.length" class="empty">{{c.t('发一句问候，开启对话。')}}</view><view v-for="m in c.messages" :key="m.id" class="message-wrap" :class="{mine:m.mine}"><view class="message-bubble"><text selectable>{{m.translation||m.content}}</text><view v-if="m.translation" class="translation-original"><button role="button" tabindex="0" class="text-button" @click="m.showOriginal=!m.showOriginal">{{c.t(m.showOriginal?'收起原文':'查看原文')}} ⌄</button><text v-if="m.showOriginal" selectable>{{m.content}}</text></view><text v-if="m.translationUnavailable" class="mini-label">{{c.t('译文暂不可用，当前显示原文')}}</text><view v-if="m.booking" class="shared-pass"><text class="eyebrow">CAMPUS PASS</text><text class="strong">{{m.booking.name}}</text><text>{{m.booking.day}} · {{m.booking.time}}</text></view></view><text class="mini-label">{{formatTime(m.time)}}</text></view></template>
   <template v-if="c.modal==='share'"><text class="muted">{{c.t('好友会收到地点、时间和预约状态。')}}</text><button role="button" tabindex="0" v-for="f in c.friends" :key="f.id" class="friend-row" :disabled="c.busy" @click="c.shareTo(f)"><view class="avatar">{{f.name.slice(0,1)}}</view><text class="strong grow">{{f.name}}</text><text>{{c.t('发送')}} ↗</text></button><view v-if="!c.friends.length" class="empty"><text>{{c.t('先与同学互相关注，再分享办事卡。')}}</text><button role="button" tabindex="0" class="soft" @click="c.modal='friends'">{{c.t('添加好友')}}</button></view></template>
