 </view>
</template>
<script setup>
import {reactive,computed,watch,nextTick,onUnmounted} from 'vue';
import {onShow} from '@dcloudio/uni-app';
import UiIcon from '../../components/UiIcon.vue';
import {useCampus} from '../../lib/useCampus';
import config from '../../config.generated';
const c=reactive(useCampus()),version=config.version;
const langs=[{value:'zh',label:'中文'},{value:'en',label:'English'},{value:'ru',label:'Русский'},{value:'ja',label:'日本語'}];
const categories=['','交友','校园生活','学习交流','日常','求助','失物招领','二手交易'],postCategories=categories.slice(1);
const tomorrow=computed(()=>{const d=new Date(c.bootstrap.today+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+1);return isNaN(d.getTime())?'':d.toISOString().slice(0,10)});
const langLabel=computed(()=>langs.find(x=>x.value===c.language)?.label||'中文');
const drawerLinks=computed(()=>[...c.mainTabs,...c.services]);
const modalTitle=computed(()=>c.modal==='chat'?c.peer?.name||c.t('好友对话'):c.t(({login:'欢迎回到校园',password:'修改密码',weather:'选择城市',reserve:'确认你的安排',receipt:'我的办事卡',post:'分享校园动态','post-detail':'校园动态',friends:'认识新朋友',share:'分享办事卡',moment:'记录一个小日常',checkin:'到场签到'})[c.modal]||''));
const partLabel=computed(()=>c.t(c.healthParts.find(x=>x.value===c.health.part)?.label||'请选择部位'));
const weatherPlace=computed(()=>c.weather?.card?.location||'');
const weatherTemperature=computed(()=>c.weather?.card?.temperature??'—');
const weatherDescription=computed(()=>c.weather?.card?.condition||'');
const healthSummary=computed(()=>typeof c.healthStep?.summary==='string'?c.healthStep.summary: c.healthStep?.summary?.text||c.healthStep?.report?.summary||'');
function slotLabel(code){return c.bootstrap.slots.find(x=>x.value===code)?.label||code}
function formatTime(value){if(!value)return '';const d=new Date(value);return isNaN(d.getTime())?String(value).slice(0,16):new Date(d.getTime()+8*3600000).toISOString().slice(0,16).replace('T',' ')}
function seatLabel(v){const match=v.name.match(/(\d+)\s*(号|座|桌|场)/);return match?match[1]:v.name}
function showReceipt(b){c.selectedBooking=b;c.modal='receipt'}
function signOut(){uni.showModal({title:c.t('退出登录'),content:c.t('确定退出当前账号？'),success:r=>{if(r.confirm)c.signOut()}})}
function endPlan(){uni.showModal({title:c.t('结束计划'),content:c.t('结束后可以恢复，已有预约不会自动取消。'),success:r=>{if(r.confirm)c.planAction('cancel')}})}
onShow(()=>{if(c.online&&c.user)c.go(c.section)});
// #ifdef H5
let focusBeforeModal,previousOverflow='';
watch(()=>c.modal,async(value,old)=>{if(value&&!old){focusBeforeModal=document.activeElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}if(value){await nextTick();document.querySelector('.modal input,.modal textarea,.modal .icon-button')?.focus()}else{document.body.style.overflow=previousOverflow;focusBeforeModal?.focus?.()}});
function modalKeys(event){if(!c.modal)return;if(event.key==='Escape'){event.preventDefault();c.closeModal()}if(event.key==='Tab'){const items=Array.from(document.querySelectorAll('.modal input,.modal textarea,.modal uni-button')).filter(x=>!x.hasAttribute('disabled')&&x.getClientRects().length);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
document.addEventListener('keydown',modalKeys);onUnmounted(()=>{document.removeEventListener('keydown',modalKeys);document.body.style.overflow=previousOverflow});
// #endif
</script>
